// Regenerates src/content/quizzes/_registry.ts from the quiz files in that folder.
// Run after adding a quiz: npm run content:registry
import { readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const dir = fileURLToPath(new URL("../src/content/quizzes/", import.meta.url));
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && !f.startsWith("_") && !f.endsWith(".test.ts"))
  .sort();
const ident = (f) => "q_" + f.replace(/\.ts$/, "").replace(/[^a-zA-Z0-9]/g, "_");
const out = [
  "// Generated by scripts/gen-registry.mjs. Do not edit by hand.",
  'import type { QuizDefinition } from "@/lib/engine/types";',
  ...files.map((f) => `import ${ident(f)} from "./${f.replace(/\.ts$/, "")}";`),
  "",
  `export const codeQuizzes: QuizDefinition[] = [${files.map(ident).join(", ")}];`,
  "",
].join("\n");
writeFileSync(dir + "_registry.ts", out);
console.log(`Registered ${files.length} quizzes`);
